from typing import Any, Dict, List, Optional, Union
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime
import hashlib
import json


@dataclass
class Run:
    """Single experiment run representation."""
    run_id: str
    experiment_id: str
    run_name: Optional[str] = None
    status: str = "RUNNING"
    start_time: Optional[datetime] = None
    end_time: Optional[datetime] = None
    params: Dict[str, Any] = field(default_factory=dict)
    metrics: Dict[str, List[float]] = field(default_factory=dict)
    tags: Dict[str, str] = field(default_factory=dict)
    artifacts: List[str] = field(default_factory=list)

    def __post_init__(self):
        if self.start_time is None:
            self.start_time = datetime.now()

    def log_param(self, key: str, value: Any):
        """Log a parameter."""
        self.params[key] = value

    def log_params(self, params: Dict[str, Any]):
        """Log multiple parameters."""
        self.params.update(params)

    def log_metric(self, key: str, value: float, step: Optional[int] = None):
        """Log a metric at a specific step."""
        if key not in self.metrics:
            self.metrics[key] = []

        entry = {"value": value, "step": step, "timestamp": datetime.now()}
        self.metrics[key].append(entry)

    def log_metrics(self, metrics: Dict[str, float], step: Optional[int] = None):
        """Log multiple metrics."""
        for key, value in metrics.items():
            self.log_metric(key, value, step)

    def set_tag(self, key: str, value: str):
        """Set a tag."""
        self.tags[key] = value

    def get_tags(self) -> Dict[str, str]:
        """Get all tags."""
        return self.tags.copy()

    def finish(self):
        """Mark run as finished."""
        self.status = "FINISHED"
        self.end_time = datetime.now()

    def to_dict(self) -> Dict:
        """Convert run to dictionary."""
        return {
            "run_id": self.run_id,
            "experiment_id": self.experiment_id,
            "run_name": self.run_name,
            "status": self.status,
            "start_time": self.start_time.isoformat() if self.start_time else None,
            "end_time": self.end_time.isoformat() if self.end_time else None,
            "params": self.params,
            "metrics": {k: [m["value"] for m in v] for k, v in self.metrics.items()},
            "tags": self.tags,
            "artifacts": self.artifacts,
        }


@dataclass
class Experiment:
    """Experiment representation."""
    experiment_id: str
    name: str
    artifact_location: Optional[str] = None
    tags: Dict[str, str] = field(default_factory=dict)
    created_time: Optional[datetime] = None

    def __post_init__(self):
        if self.created_time is None:
            self.created_time = datetime.now()

    def to_dict(self) -> Dict:
        """Convert experiment to dictionary."""
        return {
            "experiment_id": self.experiment_id,
            "name": self.name,
            "artifact_location": self.artifact_location,
            "tags": self.tags,
            "created_time": self.created_time.isoformat() if self.created_time else None,
        }


class BaseTracker(ABC):
    """Abstract base class for experiment trackers."""

    def __init__(self, experiment_name: str = "default", **kwargs):
        self.experiment_name = experiment_name
        self.experiment_id: Optional[str] = None
        self.current_run: Optional[Run] = None
        self.runs: List[Run] = []
        self.metadata: Dict[str, Any] = {}

    @abstractmethod
    def start_run(
        self,
        run_id: Optional[str] = None,
        run_name: Optional[str] = None,
        nested: bool = False,
        tags: Optional[Dict[str, str]] = None,
    ) -> Run:
        """Start a new run."""
        pass

    @abstractmethod
    def end_run(self, status: str = "FINISHED"):
        """End the current run."""
        pass

    @abstractmethod
    def log_param(self, key: str, value: Any):
        """Log a parameter."""
        pass

    @abstractmethod
    def log_params(self, params: Dict[str, Any]):
        """Log multiple parameters."""
        pass

    @abstractmethod
    def log_metric(self, key: str, value: float, step: Optional[int] = None):
        """Log a metric."""
        pass

    @abstractmethod
    def log_metrics(self, metrics: Dict[str, float], step: Optional[int] = None):
        """Log multiple metrics."""
        pass

    @abstractmethod
    def set_tag(self, key: str, value: str):
        """Set a tag."""
        pass

